from typing import Iterable, List
from hourglass.models import Shift
from hourglass.errors import ProjectError

def _tally(shifts: Iterable[Shift]) -> dict:
    totals = {}
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("shift has a blank worker name")
        count, mins = totals.get(shift.worker, (0, 0))
        totals[shift.worker] = (count + 1, mins + shift.span.minutes)
    return totals

# ---
def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker with shifts and hours, most hours first."""
    totals = _tally(shifts)
    if not totals:
        raise ProjectError("no shifts to report")
    ranked = sorted(totals.items(), key=lambda entry: (-entry[1][1], entry[0]))
    return [f"{name}: {count} shifts, {mins / 60:.1f} hours" for name, (count, mins) in ranked]
